    const METHOD: Method = Method::GET;
    const PATH: &'static str = "api/seasons/replay/{code}/{tick}";
    const AUTH: Auth = Auth::Optional;
    const FORMAT: Format = Format::Json;

    fn path(&self, path: &mut Path) {
        path.literal("api/seasons/replay/");
        path.segment(&self.code);
        path.literal("/");
        path.segment(&self.tick.to_string());
    }
