/// `GET /room-history/{shard}/{room}/{tick}.json`: Read official room-history chunk.
///
/// Official static room-history chunk served from the history host (`CONFIG.HISTORY_URL`, <https://screeps.com/room-history/>). The official client requests `<shard>/<room>/<tick>.json` with a tick aligned to `serverData.historyChunkSize` (100), treats any non-200 status as missing, and fills `room` itself when absent. A chunk holds an initial object state followed by tick-keyed diffs. The body has no `ok` envelope.
#[derive(Clone, Debug, PartialEq)]
pub struct PlatformOfficialRoomHistory {
    /// Shard name.
    pub shard: String,
    /// Room name.
    pub room: String,
    /// First tick in the history chunk.
    pub tick: u64,
}

impl Endpoint for PlatformOfficialRoomHistory {
    type Response = types::PlatformHistory;
    const METHOD: Method = Method::GET;
    const PATH: &'static str = "room-history/{shard}/{room}/{tick}.json";
    const AUTH: Auth = Auth::None;
    const FORMAT: Format = Format::Json;

    fn path(&self, path: &mut Path) {
        path.literal("room-history/");
        path.segment(&self.shard);
        path.literal("/");
        path.segment(&self.room);
        path.literal("/");
        path.segment(&self.tick.to_string());
        path.literal(".json");
    }
}

