/// `GET /room-history`: Read private-server room-history chunk.
///
/// Room-history chunk endpoint of the private-server protocol. When `options.official` is false the official web client requests `http://<host>:<port>/room-history?room=<room>&time=<tick>` with `time` aligned to `serverData.historyChunkSize`, treats any non-200 status as missing and fills `room` when absent. The body is a history chunk (base tick plus tick-keyed object diffs) without the `ok` envelope.
///
/// Standalone: `time` must identify a retained chunk base; at most `historyChunkSize` frames are returned and a missing chunk yields HTTP 404.
///
/// Standalone servers only: a private-server protocol operation of the standalone profile.
#[derive(Clone, Debug, PartialEq)]
pub struct PlatformRoomHistory {
    /// Room name.
    pub room: String,
    /// Base game tick, normally aligned to the advertised `historyChunkSize`.
    pub time: u64,
}

impl Endpoint for PlatformRoomHistory {
    type Response = types::PlatformHistory;
    const METHOD: Method = Method::GET;
    const PATH: &'static str = "room-history";
    const AUTH: Auth = Auth::None;
    const FORMAT: Format = Format::Json;

    fn query(&self, query: &mut Query<'_>) {
        query.pair("room", &self.room);
        query.pair("time", &self.time.to_string());
    }
}
